import React from "react";
import Menu from "./Menu";
import { useAuth } from "../context/AuthContext"; // 👈 1. Import authorization tracking hook
import LogoutButton from "./LogoutButton"; // 👈 2. Import your new logout button

const TopBar = () => {
  const { user } = useAuth(); // 👈 3. Fetch the logged-in username out of session state

  return (
    <div className="topbar-container" style={styles.topbarFlex}>
      {/* Your Existing Market Indices (Left Side) */}
      <div className="indices-container">
        <div className="nifty">
          <p className="index">NIFTY 50</p>
          <p className="index-points">{100.2} </p>
          <p className="percent"> </p>
        </div>
        <div className="sensex">
          <p className="index">SENSEX</p>
          <p className="index-points">{100.2}</p>
          <p className="percent"></p>
        </div>
      </div>

      {/* User Information & Logout Button Block (Right Side) */}
      <div style={styles.authWrapper}>
        <span style={styles.usernameDisplay}>
          👤 <strong>{user || "Trader"}</strong>
        </span>
        <LogoutButton />
        <Menu />
      </div>
    </div>
  );
};

// Inline helper layout extensions
const styles = {
  topbarFlex: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
  },
  authWrapper: {
    display: "flex",
    alignItems: "center",
    gap: "18px",
  },
  usernameDisplay: {
    fontSize: "14px",
    color: "#444",
    fontFamily: "Inter, sans-serif",
  },
};

export default TopBar;
